const DEFAULT_TEMPLATE_FACTURACION =
  "Hola {nombre}, le recordamos que su mensualidad de {mes} vence el {vencimiento} por un monto de {saldo}{descuentoTxto}. Agradecemos su pago puntual.";
const DEFAULT_TEMPLATE_MORA =
  "Hola {nombre}, su mensualidad de {mes} vencio el {vencimiento} y aun figura pendiente por {saldo}. Le pedimos regularizar a la brevedad. Gracias.";
const DEFAULT_TEMPLATE_COMPROMISO =
  "Hola {nombre}, le recordamos que quedamos en que realizaria su pago de {saldo} el dia {fecha}. Gracias por su compromiso.";

function ultimoDiaDelMes(year, month) {
  return new Date(year, month, 0).getDate();
}

function fechaVencimiento(m) {
  const dia = ultimoDiaDelMes(m.year, m.month);
  return m.year + "-" + String(m.month).padStart(2, "0") + "-" + String(dia).padStart(2, "0");
}

function todayISO() {
  const d = new Date();
  return d.toISOString().slice(0, 10);
}

function diffDias(fechaISO) {
  const hoy = new Date(todayISO() + "T00:00:00");
  const f = new Date(fechaISO + "T00:00:00");
  return Math.round((f - hoy) / (1000 * 60 * 60 * 24));
}

function formatFechaLegible(iso) {
  const [y, m, d] = iso.split("-");
  return d + "/" + m + "/" + y;
}

function formatSoles(n) {
  const v = Number.isFinite(n) ? n : 0;
  return "S/ " + v.toLocaleString("es-PE", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

function estadoDe(saldo, pago) {
  if (saldo <= 0) return "Pagado";
  if (pago > 0) return "Parcial";
  return "Pendiente";
}

function estadoBadgeClasses(estado) {
  if (estado === "Pagado") return "bg-green-100 text-green-800 border-green-200";
  if (estado === "Parcial") return "bg-amber-100 text-amber-800 border-amber-200";
  return "bg-gray-100 text-gray-700 border-gray-300";
}

function compromisoInfo(compromiso, saldo) {
  if (!compromiso || saldo <= 0) return null;
  const hoy = todayISO();
  if (compromiso < hoy) return { label: "Compromiso vencido", cls: "bg-red-100 text-red-800 border-red-200" };
  if (compromiso === hoy) return { label: "Compromiso hoy", cls: "bg-blue-100 text-blue-800 border-blue-200" };
  return { label: "Compromiso " + compromiso, cls: "bg-gray-100 text-gray-600 border-gray-300" };
}

function normalizePhone(raw) {
  if (!raw) return null;
  let digits = String(raw).replace(/[^0-9]/g, "");
  if (!digits) return null;
  if (digits.length === 9) digits = "51" + digits;
  return digits;
}

function fillTemplate(tpl, r, mesLabel, vencimientoLegible) {
  const descuentoTxto = r.descuento > 0 ? (" (incluye descuento de " + formatSoles(r.descuento) + ")") : "";
  return tpl
    .replaceAll("{nombre}", r.nombre)
    .replaceAll("{saldo}", formatSoles(r.saldo > 0 ? r.saldo : 0))
    .replaceAll("{mes}", mesLabel)
    .replaceAll("{vencimiento}", vencimientoLegible)
    .replaceAll("{descuentoTxto}", descuentoTxto)
    .replaceAll("{fecha}", r.compromiso || "");
}

function buildWaLink(phone, message) {
  const n = normalizePhone(phone);
  if (!n) return null;
  return "https://wa.me/" + n + "?text=" + encodeURIComponent(message);
}

